(()=>{
const products=[
{id:'breakfast',name:'Kenyan breakfast',category:'Breakfast',description:'Suggested eggs, toast and a hot drink.',image:'shop-eggs.jpg',variants:[['Light plate',350],['Full plate',550]]},
{id:'pancakes',name:'Pancakes',category:'Breakfast',description:'A sweet start or a little afternoon treat.',image:'breakfast.webp',variants:[['Regular serving',150],['Sharing serving',300]]},
{id:'tea-bites',name:'Tea-time bites',category:'Breakfast',description:'Suggested mandazi and cake selection.',image:'tea-time.webp',variants:[['For one',250],['For two',450]]},
{id:'chicken',name:'Grilled chicken meal',category:'Main meals',description:'Suggested grilled chicken with an accompaniment.',image:'shop-chicken.jpg',variants:[['Quarter portion',650],['Half portion',1100]]},
{id:'skewers',name:'Meat & vegetable skewers',category:'Main meals',description:'A proposed colourful grill selection.',image:'catering-skewers.webp',variants:[['2 skewers',400],['4 skewers',750]]},
{id:'vegetables',name:'Vegetable bowl',category:'Vegetarian',description:'A proposed seasonal vegetable selection.',image:'shop-vegetables.jpg',variants:[['Regular bowl',400],['Large bowl',550]]},
{id:'tea',name:'Tea',category:'Drinks',description:'Choose a suggested hot tea style.',image:'shop-tea.jpg',variants:[['Black tea',100],['Milk tea',150],['Masala tea',180]]},
{id:'juice',name:'Fruit juice',category:'Drinks',description:'Ask the team which flavours are available.',image:'shop-juice.jpg',variants:[['Glass · 250 ml',200],['Large · 500 ml',350]]},
{id:'buffet',name:'Classic buffet',category:'Catering',description:'Proposed one protein, two starches and vegetables. Confirm menu and inclusions.',image:'breakfast.webp',min:10,variants:[['Per guest · classic',1050],['Per guest · extended',1550]]},
{id:'grill-event',name:'Celebration grill',category:'Catering',description:'A suggested mixed grill and accompaniments for your occasion.',image:'catering-skewers.webp',min:10,variants:[['Per guest',1950]]},
{id:'tea-event',name:'Tea & snacks gathering',category:'Catering',description:'Proposed tea and light bites. Ask for the complete catering quote.',image:'tea-time.webp',min:10,variants:[['Per guest',500]]}
];
const q=s=>document.querySelector(s),money=n=>'KES '+n.toLocaleString('en-KE');let category='All',cart=[];const dialog=q('#shopping-cart');let opener;
try{const saved=JSON.parse(localStorage.getItem('joy-ripples-cart-v1')||'[]');if(Array.isArray(saved))cart=saved.filter(x=>{const p=products.find(p=>p.id===x.id);return p&&Number.isInteger(x.variant)&&p.variants[x.variant]&&Number.isInteger(x.quantity)&&x.quantity>=(p.min||1)&&x.quantity<=999}).map(x=>({id:x.id,variant:x.variant,quantity:x.quantity}))}catch{}
const categories=['All','Breakfast','Main meals','Vegetarian','Drinks','Catering'];q('#shop-categories').innerHTML=categories.map(c=>`<button type="button" data-category="${c}" aria-pressed="${c==='All'}">${c}</button>`).join('');
q('#shop-categories').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;category=b.dataset.category;renderProducts()});q('#shop-search').addEventListener('input',renderProducts);q('#shop-sort').addEventListener('change',renderProducts);
function renderProducts(){let list=products.filter(p=>(category==='All'||p.category===category)&&(p.name+' '+p.category+' '+p.description).toLowerCase().includes(q('#shop-search').value.toLowerCase().trim()));if(q('#shop-sort').value!=='featured')list.sort((a,b)=>(a.variants[0][1]-b.variants[0][1])*(q('#shop-sort').value==='low'?1:-1));q('#shop-results').textContent=`${list.length} ${list.length===1?'selection':'selections'} · estimated prices`;q('#shop-empty').hidden=!!list.length;document.querySelectorAll('#shop-categories button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)));q('#product-grid').innerHTML=list.map(p=>`<article class="product-card" data-product="${p.id}"><div class="product-photo"><img src="assets/${p.image}" alt="Illustration for ${p.name}" width="700" height="500" loading="lazy"><span>${p.category==='Catering'?'Catering proposal':'Sample dish'}</span></div><div class="product-body"><h2>${p.name}</h2><p>${p.description}</p><label for="variant-${p.id}">${p.category==='Catering'?'Package':'Choose an option'}</label><select id="variant-${p.id}" data-variant>${p.variants.map((v,i)=>`<option value="${i}">${v[0]}</option>`).join('')}</select><strong class="product-price">${money(p.variants[0][1])}<small>estimated${p.min?' / guest':''}</small></strong><div class="product-purchase"><div><label for="qty-${p.id}">${p.min?'Guests (min. 10)':'Quantity'}</label><input id="qty-${p.id}" type="number" inputmode="numeric" min="${p.min||1}" max="999" value="${p.min||1}"></div><button class="button" type="button" data-add>Add to cart</button></div></div></article>`).join('')}
q('#product-grid').addEventListener('change',e=>{if(!e.target.matches('[data-variant]'))return;const card=e.target.closest('[data-product]'),p=products.find(p=>p.id===card.dataset.product);card.querySelector('.product-price').innerHTML=money(p.variants[Number(e.target.value)][1])+`<small>estimated${p.min?' / guest':''}</small>`});
q('#product-grid').addEventListener('click',e=>{if(!e.target.closest('[data-add]'))return;const card=e.target.closest('[data-product]'),p=products.find(p=>p.id===card.dataset.product),input=card.querySelector('input'),quantity=Number(input.value),variant=Number(card.querySelector('select').value);if(!input.reportValidity())return;const line=cart.find(x=>x.id===p.id&&x.variant===variant);if(line)line.quantity=Math.min(999,line.quantity+quantity);else cart.push({id:p.id,variant,quantity});save();q('#shop-toast').hidden=false;q('#shop-toast').textContent=p.name+' added to cart';clearTimeout(toastTimer);toastTimer=setTimeout(()=>q('#shop-toast').hidden=true,2800)});let toastTimer;
function total(){return cart.reduce((sum,x)=>sum+products.find(p=>p.id===x.id).variants[x.variant][1]*x.quantity,0)}
function save(){try{localStorage.setItem('joy-ripples-cart-v1',JSON.stringify(cart))}catch{}renderCart();q('#cart-wa-fallback').hidden=true}
function renderCart(){q('#floating-cart').hidden=!cart.length;q('#floating-cart-total').textContent=money(total());q('#cart-count').textContent=cart.length;q('#cart-total').textContent=money(total());q('#cart-send').disabled=!cart.length;q('#cart-lines').innerHTML=cart.length?cart.map((x,i)=>{const p=products.find(p=>p.id===x.id),v=p.variants[x.variant];return `<article class="cart-line"><div><h3>${p.name}</h3><p>${v[0]} · ${money(v[1])}${p.min?' / guest':''}</p><strong>${money(v[1]*x.quantity)}</strong></div><div class="cart-line-controls"><label for="cart-qty-${i}">${p.min?'Guests':'Quantity'}</label><input id="cart-qty-${i}" type="number" inputmode="numeric" min="${p.min||1}" max="999" value="${x.quantity}" data-line="${i}"><button type="button" data-remove="${i}">Remove ${p.name}</button></div></article>`}).join(''):'<p class="empty-cart">Your cart is empty. Explore the menu and add a selection.</p>'}
q('#cart-lines').addEventListener('input',e=>{if(!e.target.matches('[data-line]')||!e.target.checkValidity())return;const i=Number(e.target.dataset.line),line=cart[i],p=products.find(p=>p.id===line.id);line.quantity=Number(e.target.value);try{localStorage.setItem('joy-ripples-cart-v1',JSON.stringify(cart))}catch{}q('#cart-total').textContent=money(total());q('#floating-cart-total').textContent=money(total());e.target.closest('.cart-line').querySelector('strong').textContent=money(p.variants[line.variant][1]*line.quantity);q('#cart-wa-fallback').hidden=true});
q('#cart-lines').addEventListener('change',e=>{if(!e.target.matches('[data-line]'))return;const i=Number(e.target.dataset.line);if(!e.target.checkValidity()){e.target.reportValidity();e.target.value=cart[i].quantity;return}cart[i].quantity=Number(e.target.value);save()});q('#cart-lines').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;cart.splice(Number(b.dataset.remove),1);save()});
function openCart(button){opener=button;renderCart();dialog.showModal();document.body.style.overflow='hidden'}q('#view-cart').addEventListener('click',()=>openCart(q('#view-cart')));q('#floating-cart').addEventListener('click',()=>openCart(q('#floating-cart')));q('#close-cart').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.style.overflow='';opener?.focus()});const now=new Date();q('#cart-date').min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
q('#cart-enquiry').addEventListener('submit',e=>{e.preventDefault();if(!cart.length)return;for(const input of q('#cart-lines').querySelectorAll('input')){if(!input.reportValidity())return}const name=q('#cart-name').value.trim();if(!name){q('#cart-name').setCustomValidity('Please enter your name.');q('#cart-name').reportValidity();return}const contact=q('#cart-recipient').value==='joyce'?{name:'Joyce',phone:'254722165863'}:{name:'Isaac',phone:'254722693407'};const lines=cart.map(x=>{const p=products.find(p=>p.id===x.id),v=p.variants[x.variant];return `${p.name} — ${v[0]} × ${x.quantity}${p.min?' guests':''}: ${money(v[1]*x.quantity)} estimate`});const message=`Hello ${contact.name}, please quote for this Joy Ripples enquiry.\nName: ${name}\nPreferred date: ${q('#cart-date').value}\n\n${lines.join('\n')}\n\nEstimated item subtotal: ${money(total())}\nDetails: ${q('#cart-notes').value.trim()}\n\nThese are website sample selections and benchmark estimates. Please confirm availability, actual prices, catering inclusions, logistics, fees and applicable taxes. This is not a confirmed order.`;const a=q('#cart-wa-fallback');a.href='https://wa.me/'+contact.phone+'?text='+encodeURIComponent(message);a.hidden=false;window.open(a.href,'_blank','noopener,noreferrer')});q('#cart-name').addEventListener('input',()=>q('#cart-name').setCustomValidity(''));q('#cart-enquiry').addEventListener('input',()=>q('#cart-wa-fallback').hidden=true);q('#cart-enquiry').addEventListener('change',()=>q('#cart-wa-fallback').hidden=true);renderProducts();renderCart();
})();
